  "version": "1.0.0"
}
```

These are the functions available to you:

```ts
/** Change the executor's working directory to an existing directory and return its absolute path. Relative paths resolve from the current directory without shell expansion. Await this before dependent tools. The change persists across scripts and is shared with delegates using this executor. Startup AGENTS.md, skills, and the semantic-search index root remain fixed. Navigation does not survive a session reload. */
declare function changeDirectory(directory: string): Promise<string>

/** Read a file and optionally filter the lines to return. Returns null if the file doesn't exist. For png/jpeg/gif/webp files the image itself is attached to your next turn and a short marker is returned instead of the bytes; line ranges are not allowed on images. */
declare function readFile(options: {
    readonly path: string;
    readonly startLine?: number | undefined;
    readonly endLine?: number | undefined;
}): Promise<string | null>

/** Search for a pattern in files using ripgrep */
declare function rg(options: {
    readonly pattern: string;
    /** --glob */
    readonly glob?: string | undefined;
    /** Only return file paths --files-with-matches */
    readonly filesOnly?: boolean | undefined;
    /** The total maximum number of lines to return across all files (default: 500) */
    readonly maxLines?: number | undefined;
}): Promise<string>

/** Find files matching a glob pattern. */
declare function glob(pattern: string): Promise<readonly string[]>

/** Run a bash command and return the output */
declare function bash(command: {
    readonly command: string;
    /** Timeout in ms (default and max: 180000) */
    readonly timeoutMs?: number | undefined;
}): Promise<string>

/** Add, update or remove multiple files with a git diff / unified diff / wrapped patch. */
declare function applyPatch(patch: string): Promise<string>

/** Write content to a file, creating parent directories if needed. */
declare function writeFile(options: {
    readonly path: string;
    readonly content: string;
}): Promise<void>

/** Remove a file. */
declare function removeFile(path: string): Promise<void>

/** Rename or move a file, creating parent directories if needed. */
declare function renameFile(options: {
    readonly from: string;
    readonly to: string;
}): Promise<void>

/** List the contents of a directory */
declare function ls(directory: string): Promise<readonly string[]>

/** Sleep for a specified number of milliseconds */
declare function sleep(ms: number): Promise<void>

/** Only call this when the task is fully complete and you have a final output message to send. */
declare function taskComplete(output: string): Promise<void>

/** Report one review finding on the pull request. `path` is a file the PR changes and `line` (optionally through `endLine`) are new-side line numbers that lie inside the PR diff hunks; anchors outside the diff are rejected. Returns the finding id, which `updateThread` takes. */
declare function reportFinding(options: {
    readonly path: string;
    readonly line: number;
    readonly endLine?: number;
    readonly severity: "blocking" | "suggestion" | "nit" | "question";
    readonly title: string;
    readonly body: string;
}): Promise<{
    readonly id: string;
}>

/** Append a comment to the thread of a finding reported earlier in this review, for example a test or probe result that confirms or withdraws it. Returns the thread's comment count. */
declare function updateThread(options: {
    readonly id: string;
    readonly body: string;
    readonly resolve?: boolean;
}): Promise<{
    readonly id: string;
    readonly comments: number;
}>

/** The global Fetch API available for making HTTP requests. */
declare const fetch: typeof globalThis.fetch
